  "implementation": "def solve(case):
    memory = []
    signatures = []
    seen = set()
    for i, trial in enumerate(case['trials']):
        entry = {
            'last_trial': i,
            'reflection': trial['reflection'],
            'signature': trial['signature'],
            'success': trial['success']
        }
        memory.append(entry)
        if len(memory) > case['capacity']:
            memory.pop(0)
        if trial['signature'] not in seen:
            seen.add(trial['signature'])
            signatures.append(trial['signature'])
    return {
        'memory': memory,
        'signatures': signatures
    }"
}
